"use client";
/* eslint-disable @next/next/no-html-link-for-pages */
import{useEffect}from"react";import{getSupabaseBrowserClient}from"../lib/supabase/client";
export default function AppError({error,reset}:{error:Error&{digest?:string};reset:()=>void}){useEffect(()=>{const report=async()=>{const sb=getSupabaseBrowserClient();if(!sb)return;const{data:{user}}=await sb.auth.getUser();await sb.from("client_error_reports").insert({user_id:user?.id||null,route:window.location.pathname,message:error.message.slice(0,500),error_digest:error.digest||null,context:{online:navigator.onLine,user_agent:navigator.userAgent.slice(0,200)}})};void report()},[error]);return <main className="error-recovery"><span>V</span><p>Vector Golf Performance</p><h1>That page could not finish loading.</h1><p>Your saved database information has not been changed. If you were entering a round offline, check Sync after reopening the app.</p><div><button onClick={reset}>Try again</button><a href="/">Return home</a></div><small>Error reference: {error.digest||"not available"}</small></main>}
